CROSS JOIN (VALUES
  ('A2_SH01', $pp${"positivePrompt": "{STYLE}, {PALETTE_A2}, extreme wide shot from high angle over central Mogilev in October 2018, five-storey panel apartments and a few taller new business buildings, golden poplar and birch trees lining streets, yellow leaves falling pedestrians in light autumn jackets a few cars parked along Mira avenue, overcast cool grey-white autumn sky with weak directional sun behind clouds long shadows at low angle, hard ink outline cell-shaded muted autumn ochre and cool grey, EWS high angle locked off 16:9", "negativeRef": "{NEG}", "narrationRu": "Октябрь две тысячи восемнадцатого, Могилёв, тебе тридцать восемь"}$pp$, 'EWS', 'high', 'static', 'rising', 'atmosphere', NULL, TRUE, FALSE, 'october_day_2018', 'A2_corporate_teal'),
